INSERT INTO theory_content (chapter_slug, subject_id, concepts_json) VALUES ('telangana-history-en-chapter11-qutbshahi-rule', 'telangana-history-en', '') ON CONFLICT(chapter_slug) DO UPDATE SET concepts_json = '';
UPDATE theory_content SET concepts_json = concepts_json || '[{"partNumber": 1, "conceptId": "telangana-history-en-chapter11-qutbshahi-rule-p1", "partName": "Origins and Foundation of the Qutb Shahi Kingdom", "bodyMd": "The Qutb Shahi kingdom emerged on the ruins of the Bahamani Kingdom, with Golconda as its capital. The dynasty''s ancestral home was Hamdam in Iraq (Persia), and the ancestors of Sultan Quli, the founder, migrated to India after losing power in Persia.\n\n**Founder''s early career:**\n\n*   Sultan Quli was appointed ''Tarfdar'' of Telangana by the Bahamani Sultan in 1492 CE.\n*   He declared independence in 1518 CE.\n*   He and his successors ruled most of present Telangana–Andhra areas for a period of more than 175 years.\n\nUnder Qutb Shahi rule, people enjoyed complete religious freedom, and the rulers respected local culture and treated local people like their own children. The region saw all-round development — beautiful mosques, palaces, sarais, bridges, and forts were constructed, and Telugu language also made great progress during this age.\n\n**Decline:** The kingdom witnessed regular attacks from Mughal emperors after Akbar''s death, and it was finally captured by Aurangzeb in 1687 CE.", "free": true}, {"partNumber": 2, "conceptId": "telangana-history-en-chapter11-qutbshahi-rule-p2", "partName": "Sources for the Study of Qutb Shahi History", "bodyMd": "A large number of archaeological and literary sources helps in studying Qutb Shahi history. Archaeological sources include inscriptions, coins, and monuments. Books written in Persian, Arabic, Urdu, and Telugu by poets, historians, and scholars also provide useful information, as do foreign travel accounts left by contemporary visitors, traders, and Farmans issued by Qutb Shahi Sultans.\n\n### Archaeological Sources — Inscriptions\n\n| Ruler / Officer Issued | Name of Inscription | Period | Remarks |\n|---|---|---|---|\n| Shitabkham | Warangal | 1504–1506 CE | Restoration of Hindu temples in this region |\n| Ibrahim-Quli Qutb Shah | Nalgonda (District) Ghazinagar | 1576–1577 CE | — |\n| Muhammad-Quli Qutb Shah | Badshah-e-Ashur Khana | 1592–1596 CE | — |\n| Muhammad-Quli Qutb Shah | Daru-Shifa | 1595 CE | — |\n| Abul Hasan Tanashah | Miyam-Misq | 1681 CE | — |\n| Musunuri Prolayanayaka | Vilasa Copper Plate | 1323–1324 CE | Gives a clear picture of oppressive Muslim rule in the Telugu country |\n\n### Literary Sources\n\n| Book / Work | Author | Remarks / Useful Information |\n|---|---|---|\n| Khazain-ul-Futuh and Nuh Sipihr | Amir Khusrav | Describes the general conditions of the Deccan during the 14th century |\n| Tariq-e-Ferishta (or Gulshan-e-Ibrahimi), Persian | Muhammad Qasim Ferishta | Describes the political condition of the Deccan; used the term ''Telang'' for modern Telangana. Ferishta was born in 1552 CE at Astrabadi, Iran; joined the court of Ibrahim Adilshah of Bijapur and dedicated his work to him. Five pages of this work contain useful information |\n\nForeign travel accounts (Tavernier, Bernier, Thevenot, Methwold and others) and the Farmans issued by the Sultans supplement these inscriptional and literary sources for the study of Qutb Shahi political, social, and cultural life.", "free": true}, {"partNumber": 3, "conceptId": "telangana-history-en-chapter11-qutbshahi-rule-p3", "partName": "Qutb Shahi Sultans (1518–1687 CE)", "bodyMd": "Qutb Shahi Sultans ruled Telugu-speaking areas of present Telangana, Andhra, and Rayalaseema for more than one hundred and seventy-five years.\n\n| Sultan | Period of Rule | Key Events |\n|---|---|---|\n| Quli-Qutb-ul-Mulk | 1518–1543 CE | Founder of the dynasty; capital Golconda; contemporary of Srikrishnadevaraya and Achyutadevaraya of Vijayanagara, Babur (founder of Mughal rule), and Shershah-Sur |\n| Jamsheed-Quli | 02.09.1543 – 27.07.1550 CE | Greedy for power; murdered his aged father and ascended the throne; died of cancer |\n| Subhan-Quli | Few months from July 1550 | Son of Jamsheed; ascended the throne at the young age of 7 |\n| Ibrahim-Quli-Qutb Shah | 1550–1580 CE | Sixth son of the founder; escaped to Vijayanagara court fearing his life from elder brother Jamsheed; sheltered by Aliya Ramaraya |\n| Muhammad-Quli-Qutb Shah | 1580–1612 CE | Third son of Ibrahim-Quli; ascended the throne at age 14; built Hyderabad and Charminar; good friend of Akbar; developed diplomatic relations with Iran |\n| Muhammad-Qutb Shah | 1612–1626 CE | Mughal invasions on Golconda started during this period |\n| Abdullah-Qutb Shah | 1626–1676 CE | Contemporary of Mughal emperors Jahangir and Shahjahan; Golconda faced serious Mughal invasions during his reign |\n| Abul Hassan Tanashah | 1676–1687 CE | Last Qutb Shahi Sultan; defeated in 1687 CE by Aurangzeb; imprisoned at Daulatabad fortress, where he died in 1699 CE |", "free": false}, {"partNumber": 4, "conceptId": "telangana-history-en-chapter11-qutbshahi-rule-p4", "partName": "Qutb Shahi Sultans", "bodyMd": "### Sultan-Quli-Qutb-ul-Mulk (1518–1543 CE)\n\nSultan-Quli-Qutb-ul-Mulk was the founder of the independent Golconda kingdom in 1518 CE. He was a contemporary of the last Delhi Sultan Ibrahim Lodi, Krishnadevaraya of Vijayanagara, Yousuf Adilshah of Bijapur, and the last Bahamani Sultan Muhammad Shah.\n\n**Early life and rise:**\n\n*   His ancestors hailed from Hamdam in Southern Iran; he was born there in 1451 CE to Sher-Quli and Malik Swalch, of the ''Qara Quyunlu'' tribe.\n*   He migrated to India along with his uncle Ali-Quli after they lost power to the ''Akunev'' tribe, reaching Gulbarga, the Bahamani headquarters, during the reign of Muhammad-Shah III (1463–1482 CE).\n*   The execution of Muhammad-Gawan, the Bahamani Prime Minister, in 1481 pushed the kingdom into political confusion; the new Sultan, Shihabuddin Mahmood, was not capable, and a plot by the Sultan''s rivals to kill him was cleverly foiled by Quli — impressing the Sultan.\n*   He was appointed ''Tarfdar'' of Telangana in 1492 CE, crushed the revolts there, and established peace.\n\n**Founding of the kingdom:**\n\n*   By 1518 CE, Quli had also seized Golconda Fort. After the death of the last Bahamani Sultan, Quli declared his independence in 1518 CE, at the age of sixty-seven.\n*   He and his successors ruled Telugu-speaking areas of present Telangana, Andhra Pradesh, and some parts of Karnataka; he ruled as an independent ruler till 1543 CE.\n*   He was a contemporary of Vijayanagara rulers Saluva Narasimharaya, Srikrishnadevaraya, and Achyutadevaraya.\n\n**Conquests:** He attacked the territories of the Reddy, Vijayanagara, and Gajapati rulers, capturing some portions; the Gajapati officer at Warangal, Sitapati (Shitabkham), was defeated in the Battle of Khammammet.\n\n**Building activity:** He strengthened and improved Golconda fort, constructing many buildings, mosques, and palaces, and built a new city, ''Muhammad Nagar'', near Golconda fort. He also attacked Vijayanagara territories after Srikrishnadevaraya''s death, when internal succession struggles broke out, extending his authority from Kohir, Warangal, and Nalgonda up to Masulipatnam.\n\nHe was murdered by his own son Jamsheed inside a mosque in Golconda fort, at the age of 99. According to tradition, Jamsheed engineered the killing through his trusted agent Mir Mahmood, who struck down the aged Sultan-Quli with a sword while he was consulting with masons and architects about mosque construction after Friday prayers.\n\n**Sons and the succession struggle:** Sultan-Quli''s six sons were Hyder-Quli, Qutbuddin, Jamsheed-Quli, Abdul-Karim, Dowlat-Quli, and Ibrahim. In the struggle that followed, Qutbuddin was blinded and imprisoned; Abdul-Karim conspired for the throne with Bijapur''s help while his father was still alive and died at Bijapur; Dowlat-Quli was imprisoned by Jamsheed at Bhongir fort; and Ibrahim, the youngest, fled to Vijayanagara.\n\n### Jamsheed-Quli-Qutb Shah (1543–1550 CE)\n\nSultan-Quli''s last days were not peaceful — his six sons (Hyder-Quli, Qutbuddin, Jamsheed-Quli, Abdul-Karim, Dowlat-Quli, and Ibrahim) fought over the throne. Jamsheed-Quli, the third son, murdered his aged father and ascended the throne.\n\nHis seven-year reign was filled with wars, revolts, and confusion; the people and most officials disliked him. The contemporary Deccani Sultans of Ahmednagar and Bijapur, along with the Vijayanagara king, attacked Golconda territories and captured some portions.\n\n**Administrative significance:** Despite the turmoil, Jamsheed-Quli attempted to introduce a strong administrative system — Kamaluddin-Ardistani was his most capable minister; the Sultan held the highest position in central administration, with Vakil, Peswa, and Mir-Jumla as other important ministers.\n\nHe died of cancer in 1550 CE.\n\n### Ibrahim-Quli-Qutb Shah (1550–1580 CE)\n\nAfter Jamsheed-Quli''s death, Subhan-Quli, his seven-year-old son, was declared Sultan by his mother and some self-serving nobles, with administrator Saif Khan running the actual affairs of the kingdom. \n\nSaif Khan''s misrule and revolt against the young Sultan and queen mother is said to have triggered the recall of Ibrahim-Quli-Qutb Shah, who had been living in exile at the Vijayanagara court. Ibrahim-Quli-Qutb Shah — the youngest son of the founder, Sultan-Quli — returned to Golconda with the help of Aliya Ramaraya, the de facto ruler of Vijayanagara, and seized the throne in 1550 CE, ruling till 1580 CE.\n\nHistorian Haroon-Khan-Sherwani, in his classical work _History of the Qutb Shahi Dynasty_ (1974), described this reign as **\"the kingdom at its height.\"** He was a contemporary of the Mughal emperor Akbar, and friendly diplomatic relations existed between Golconda and the Mughals.\n\n**Military affairs and the Battle of Raksasi-Tangadi:**\n\n*   Ibrahim-Quli made elaborate arrangements to expand his kingdom, fighting Deccan Sultans and the Vijayanagara ruler.\n*   Aliya Ramaraya''s divide-and-rule policy against the Deccani Sultans caused them great loss; by 1564 CE, the Sultans realized their mistake of disunity.\n*   Ibrahim-Quli united the Deccan Sultans through matrimonial alliances between Golconda, Ahmednagar, and Bijapur royal families — Ibrahim-Quli himself married Bibi Jamal, sister of the Ahmednagar ruler; Chand Bibi of Ahmednagar was married to Ali Adilshah of Bijapur, while her brother, the Nizamshah''s son, married Ali Adilshah''s sister; and the Bidar ruler was also linked into this network of alliances, binding the coalition together as one extended family opposed to Aliya Ramaraya.\n*   The combined armies of Golconda, Ahmednagar, and Bijapur, led by Ibrahim-Quli, met the Vijayanagara forces led by Aliya Ramaraya and his brothers in the historic **Battle of Raksasi-Tangadi in January 1565 CE**.\n*   The Deccani Sultans defeated and killed Aliya Ramaraya in the battlefield, plundering the Vijayanagara capital; the victory enhanced the glory of Golconda and Ibrahim-Quli.\n\n**Ministers and officials:** Mustafa-Khan was his most experienced minister of military affairs; Amir-Shah, Muhammad-Anju, and Hussain Baig were other important officials who helped consolidate the Golconda army.\n\n**Fortification and irrigation:** He strengthened Golconda fort with high walls and constructed many tanks to supply water for agriculture, including Hussain Sagar and the Ibrahimpatnam tank. Agriculture, trade, and commerce flourished during his age. He also established friendly, diplomatic relations with the Safavid rulers of Persia.\n\n**Patronage of learning:** Ibrahim-Quli was a great scholar and patron of poets and scholars. Telugu poets Addanki Gangadhara Kavi (author of _Thapathi-Samvaranophakhyanam_) and Kandukuri Rudra Kavi (author of _Nirankushophkhyanam_) received his patronage, and he was praised by scholars as ''Malkibhirama.''\n\nHe died in 1580 CE; the Golconda kingdom made all-round progress during his reign.\n\n### Muhammad-Quli-Qutb Shah (1580–1612 CE)\n\nMuhammad-Quli-Qutb Shah succeeded his father Ibrahim-Quli, who had trained him in state affairs. He was remembered in medieval Deccan history for his grand works and great abilities — a great scholar in Deccani Urdu with knowledge of Telugu as well. \n\n**Relations with contemporary rulers:**\n\n| Ruler | Dynasty | Remarks |\n|---|---|---|\n| Akbar | Mughal | Friendly diplomatic relations existed |\n| Jahangir | Mughal | Mughal–Golconda relations |\n| Ibrahim Adilshah-II | Adilshahi (1580–1627 CE) | Wars between them |\n| Venkatapatiraya-II | Aravidu | Vijayanagara wars between them |\n| Chand Bibi | Ahmednagar | — |\n| Shah Abbas | Safavid | Diplomatic and cultural contacts existed |\n| Queen Elizabeth | England | Granted permission to London traders to found the East India Company |\n\n**Founding of Hyderabad:** He built Hyderabad city; his peshwa Mir-Momin-Astrabadi designed the plan for the city and Charminar. The new city became the centre of composite culture, attracting scholars, artists, traders, and Afaquis who migrated there during his reign.\n\n**Wars with Bijapur and Vijayanagara:**\n\n*   He waged war with the Bijapur Sultan; a peace treaty was concluded in 1581 CE.\n*   Alikhan-loor, a Golconda commander, revolted against the Sultan with the support of Venkatapathiraya-II of Vijayanagara; Golconda''s first attempt to recapture territory failed due to heavy floods on the river Krishna.\n*   A second attempt after 1585 CE, led by Amin-ul-Mulk, succeeded in capturing Kurnool, Gutti, Udayagiri, and Penugonda; Venkatapathiraya-II then concluded a peace treaty with Golconda.\n\n**Suppression of revolts:** Commander Ain-ul-Mulk suppressed revolts of Bhalevar, Alam Khan (Kondavidu), and Mukundaraja Bahubalendra (Kasimkota), and also suppressed revolts of Elur and Rajahmundry Sardars. The Golconda army invaded Ahmednagar in 1597 CE, defeating Chandbibi.\n\n**Mughal relations:** He received Akbar''s envoy Masood Baig with great respect and sent costly gifts to the Mughal emperor. Friendship continued till Akbar''s death in 1605 CE; Jahangir''s attacks on Golconda thereafter damaged this friendship.\n\nMuhammad-Quli-Qutb Shah died in 1612 CE.\n\n### Sultan-Muhammad-Qutb Shah (1612–1626 CE)\n\nSultan-Muhammad-Qutb Shah, son of Mirza-Muhammad-Amin and nephew of Muhammad-Quli, became Sultan of Golconda in November 1612 CE. He married Hayat-Baksh-Begum, daughter of Muhammad-Quli-Qutb Shah, and ruled for fourteen years. His mother was ''Khanam Agha,'' belonging to the family of Imam Musakhajim, head of the Shia sect. Diplomatic relations between the Qutb Shahis and Mughals strained during this period.\n\nHe was a peace-loving Sultan and a great believer in Islamic principles, avoiding wars and plots. His peshwa Meer-Momin-Astrabadi, and successor Allam-Ibn-i-Khatan-Amooli, managed state affairs between 1612 and 1626.\n\n**Mughal pressure and the peace treaty:**\n\n*   Malik Amber, Prime Minister of Ahmednagar, influenced the course of Deccan politics; internal developments in Bijapur and Ahmednagar worried the security of the Qutb Shahi king' WHERE chapter_slug = 'telangana-history-en-chapter11-qutbshahi-rule';
UPDATE theory_content SET concepts_json = concepts_json || 'dom.\n*   Malik Amber''s defeat at the hands of Mughal prince Khurram terrified the rulers of Bijapur and Golconda; Mughal forces defeated Qutb Shahi forces, and a peace treaty was concluded between the defeated Sultan and emperor Jahangir.\n*   Sultan-Muhammad gave gifts worth fifteen lakhs to the Mughal emperor.\n*   According to _Iqbal-Nama_, when Mughal prince Khurram revolted against Noorjahan (Jahangir), Sultan-Muhammad refused to help Khurram but permitted him to reach Bengal via Musulipatnam.\n\n**Building and cultural activity:** Only the Masab-Tank and Khairatabad Mosque were constructed during his period, and he laid the foundation for the Mecca Masjid. He was a good scholar of Persian. Mir-Momin-Astrabadi wrote _Risala-e-Mikdaria_, a Persian work on weights and measurements.\n\n**Foreign relations and trade:** He was a good friend of Shah Abbas of Persia; the Persian ambassador Hassan-Baig-Khifaqui spent two years at his court. European trading companies established trading centres at Masulipatnam, Pulicat, Nagapatnam, and Nizampatnam during his reign.\n\nHe died at the age of 34.\n\n### Abdullah-Qutb Shah (1626–1672 CE)\n\nAbdullah-Qutb Shah ascended the Golconda throne at the age of fifteen. His mother, Hayat-Baksh-Begum, managed state affairs during his early years. The Mughal rulers Shahjahan and Aurangzeb made regular attacks on Golconda during his period. He suffered a defeat at Mughal hands in 1636 CE and accepted a subordinate position.\n\n**Court factionalism:**\n\n*   Nobles and officials of the court divided into groups, threatening the integrity of the Golconda State.\n*   The Sultan entrusted state affairs to his Prime Minister Allama-Ibn-Khatun, a Persian Afaqui; the Deccani Sardars disliked his activities and policies, creating differences between the two sections.\n*   The removal of Muhammad-Raza, a native Deccani, from the post of Dabir by Ibn-Khatun, and the appointment of Persians and Afaquis (Moulana-Bawain, Meer-Qasim, Hakim Nizamuddin Ahmed, Iklaskhan, and others) to higher positions, forced the Deccani Sardars to revolt against Ibn-Khatun.\n*   After Ibn-Khatun''s dismissal, Muhammad-Syed-Arbastani, Governor of the Karnataka region, gathered a huge army and revolted against the centre; he later became Mir-Jumla, with Gandikota as his headquarters.\n\n**Diplomatic honours:** During his reign, the Council of Ministers (Majlis-i-Diwandari) attained complete perfection, meeting daily. Abdullah-Qutb Shah promoted his minister Ain-ul-Mulk ''Yusufshah'' as the Qutb Shahi ambassador at the Court of Jahangir in 1630 CE.\n\n### Abul-Hasan-Tanashah (1672–1687 CE)\n\nAbul-Hasan-Tanashah was the last Qutb Shahi ruler — a contemporary of Aurangzeb and Shivaji, and son-in-law of Abdullah-Qutb Shah. He faced the attacks of Mughal forces with firm determination and was known for his religious tolerance, appointing Akkanna, Madanna, and Kancharla Gopanna to responsible positions, all of whom worked for the welfare of the people.\n\n**The fall of Golconda:**\n\n*   Akkanna and Madanna were killed by their opponents in 1686 CE.\n*   Aurangzeb''s forces captured Golconda in 1687 CE; all the brave efforts of Abul-Hasan-Tanashah''s army failed due to Abdullah-Phani''s greed and Aurangzeb''s tactics.\n*   The gates of Golconda were opened to Mughal forces by the disloyal Qutb Shahi officer Abdullah-Phani.\n*   The Sultan was arrested and first imprisoned at Bidar fort, then shifted to Daulatabad fortress, where he died in 1699 CE. Golconda became part of the Mughal empire.", "free": false}, {"partNumber": 5, "conceptId": "telangana-history-en-chapter11-qutbshahi-rule-p5", "partName": "Administration of Qutb Shahis", "bodyMd": "The administrative system introduced by the Qutb Shahi Sultans was unique in nature and structure, providing sound and popular administration to their subjects.\n\n### Sources for Administrative History\n\nMirza-Ibrahim-Zubari''s work _Basatin-us-Salatin_ (_Dastur-ul-Amal_) provides very useful, authentic information about Qutb Shahi polity, its nature, and structure.\n\nZubari was a contemporary of Abdullah-Qutb Shah (1626–1672). The book was written on the model of _Siasat Nama_, written by Nizam-ul-Mulk-Tusi, court scholar of Sultan-Malik-Shah-Seljuki, ruler of Central Asia — a work that discussed the duties and objectives of a Sultan. The Qutb Shahi Sultans followed the guidelines laid out in _Siasat Nama_, while also honouring local peoples'' desires and local laws in running the administration.\n\n**Key advice recorded in Basatin-us-Salatin:**\n\n1.  **On kingship and justice:** In the first part, the author advised the king to protect the law and follow it without fear or favour, saying such a spirit would bring good name to the ruler and prosperity to the kingdom.\n    *   If the ruler treats all subjects with love and takes care of the needy in a just way, he becomes popular.\n    *   The Sultan should appoint Quzis, Muftis, and Judges and pay their salaries in cash.\n    *   Donation of some villages to these officials was also supported.\n2.  **On ministers:** In the second section, the author advised the Sultan to appoint ministers based on loyalty, experience, and dedication.\n    *   Jagirs should be granted to ministers for a period of three years.\n    *   Strict discipline should be maintained with ministers.\n    *   The Sultan should conduct himself in council meetings with high dignity.\n3.  **On public welfare works:** The author advised the Sultan to undertake:\n    *   Construction of trunk roads\n    *   Keeping feeder roads clean\n    *   Making arrangements for the public to purchase required articles during festival days\n    *   Planting shady trees on both sides of roads\n    *   Construction of Sarais, with arrangement of water and free feeding facility funded by the government\n\nAll these suggestions were followed by Qutb Shahi Sultans with true spirit, which made them very popular.\n\n### Central Government\n\n**A) Sultan** — The Sultan was head of the Central Government, enjoying extensive powers. He claimed divine right, calling himself ''Zillullah'' (the image of God). \n\nAs Head of State, he was chief of all organs of power — legislature, judiciary, and executive — the only law-giver and Supreme Commander of the armed forces. He lived in grand style and rarely came out of his palace except to receive very important guests. \n\nAccording to an envoy of Shah Abbas of Persia who visited Abdullah-Qutb Shah''s court in 1636–37 CE, the envoy was very much surprised to see the Sultan''s palace, dress, and headgear studded with costly diamonds and gems — even the ministers and high officials lived in grand buildings. Events like birthdays, marriages, and victory celebrations were held grandly, with costly presents received from foreign rulers on such occasions.\n\n**B) Council of Ministers / Privy Council (Majlis-i-Diwandari)** — This body, after the Sultan, played a key role in administration and consisted of powerful, high officials whose laws were respected by all members.\n\n*   Under Ibrahim-Quli-Qutb Shah, the Council was popularly known as ''Majlis-i-Kingash'' and met only for emergency issues.\n*   Under Abdullah-Qutb Shah, the Majlis-i-Diwandari attained complete perfection and met every day.\n*   The Sultan also promoted some Majlis members to the position of ambassadors — e.g., Abdullah-Qutb Shah promoted his minister Ain-ul-Mulk ''Yusufshah'' as Qutb Shahi ambassador at the court of Jahangir in 1630 CE.\n\n**Key Central Offices:**\n\n| Office | Role | Notable Holders |\n|---|---|---|\n| Peshawa / Vakil / Prime Minister | Second in command after the Sultan; later renamed ''Diwan'' | Mustafa Khan-Arbistani; Sheik-Muhammad-Ibnkhatoon; Madanna |\n| Meer-Jumla | Finance Minister; collected taxes and customs | Mir-Momin; Mansur-Khan-Habashi; Muhammad-Said-Ardistani |\n| Ain-ul-Mulk | Minister of Military Affairs | Saif-Khan; Mansoor-Khan |\n| Nazir | Upheld law, order and ethics | Abu-Talib; Meer-Qasim |\n| Majumdar | Chief Auditor-General | Narayan Rao |\n| Dabir | Head of Diwan-e-Insha; translated Farmans | Qazi-Muzaffar Ali; Moulana-Owaisi |\n| Kotwal | Commissioner of Police | — |\n| Sarkhel | Chief Revenue Officer, capital city | Muhammad-Taqi-Shafirul-Mulk; Mirza-Roz Bihan; Sayyed Muzaffar |\n| Hawaldar | In-charge of go-downs and royal stables | — |\n\nThe Peshwa was paid a salary of twelve thousand Hons and, by the period of Abul Hassan-Tanashah, the post was converted into the office of Diwan; Madanna was the last Diwan of Golconda. The Meer-Jumla, also called Jumla-Tul-Mulk, allocated funds to each department and supervised all departmental accounts — Muhammad-Said-Ardistani rose to this post from the lowest position of Royal Records Keeper through hard work and wisdom, becoming very popular in the kingdom. \n\nThe Ain-ul-Mulk also appointed Taraf-level military officers and prepared war strategies, since the Sultan''s safety depended on this department''s efficiency. The Majumdar''s staff checked the accounts of all departments, and the Qutb Shahi Sultans preferred Hindus for this post. The Dabir also stamped Farmans approved by the Sultan and Council. The Kotwal''s systematic functioning was praised by travellers Tavernier, Thevenot, and Bernier, and his office checked every person entering the capital city.\n\nThe Sarkhel also exercised powers over provincial officers and supervised the activities of foreign traders on the East Coast. The Hawaldar was appointed from among trusted men of the Sultan.\n\n### Provincial and Local Administration\n\nLike other medieval rulers, the Qutb Shahi Sultans divided their kingdom into a number of Tarafs or Smits.\n\n*   Under Abdullah-Qutb Shah there were six Tarafs; according to Dutch Company records, the Tarfdar of Masulipatnam once disobeyed the Sultan''s orders and returned gifts sent to him.\n*   Important Smits of the kingdom included Vinkonda, Kondapalli, Masulipatnam, Eluru, Rajahmundry, Visakhapatnam, and Bellamkonda.\n*   Under the last Sultan, Abul-Hasan-Tanashah, the kingdom was divided into **37 Sarkars and 517 Parganas**. The head of a port-town was known as Shah Bandhar. Land revenue collection rights were auctioned to the highest bidders, known as ''Mustagirs.'' Machilipatnam alone fetched more than one lakh eighty thousand pagodas yearly.\n\n**Local Government:** Provinces and Smits were divided into small units, with villages as the foundation of the entire administration. Farmans mention offices such as Deshpande, Deshmukh, Thanedar, and Sthalakarni. The head of the village was called ''Maqadum''; Kulkarni was the Village Accountant, and Deshpande was the Pargana-level Accounts Officer.\n\n### Military System\n\nThe Qutb Shahi Sultans organized their military system on the model of the Bahamani Sultans with minor changes.\n\n*   A strong, efficient standing army was maintained under the direct control of the Sultan and stationed at the capital city.\n*   Golconda''s armies faced the strong challenge of contemporary Deccani Sultans, Vijayanagara, and Mughal rulers.\n*   The military department was headed by Ain-ul-Mulk. The Sultan granted Jagirs to Tarafdars to maintain a fixed number of armed forces.\n*   The army consisted of Hindu, Muslim, and Irani soldiers. A huge amount from the treasury/revenue was allocated to maintain the army — according to one version, during Abul-Hassan-Tanashah''s period, eight lakhs, eighty-four thousand, four hundred and seventy-seven Hons were spent yearly on army salaries.\n*   According to French traveller Thevenot, the monthly salary of a Muslim soldier was ten Hons.\n*   All forts were well built and stationed under experienced Fort Commanders. The uninterrupted wars with Mughals, Marathas, Deccani Shia Sultans, and Vijayanagara kept the Qutb Shahi army alert. Sirlaskhar led the army during campaigns.\n\n### Land Revenue System\n\nAgriculture remained the primary occupation of the majority, and land revenue was the chief source of income for the imperial treasury. Like the Kakatiyas, the Qutb Shahi Sultans made sincere attempts to encourage agriculture by constructing tanks and canals; the tax burden on peasants was normal. The tiller of the land was described as ''Royat'' in contemporary sources.\n\nAccording to contemporary scholar Girdharilal Asqur, in his work _Tariq-e-Zafrah_, the total revenue of the State in 1685–86, from 21 Sarkars, was **82,95,196 Hons**.\n\n**Revenue Divisions and Receipts (from H.K. Sherwani, _History of the Qutb Shahi Dynasty_, 1974, p. 655):**\n\n| Sarkar | Parganas | Total Revenue (Hons) |\n|---|---|---|\n| Muhammad Nagar | 22 | 15,37,739-13 Annas |\n| Medak | 16 | 35,16,089-6 Annas |\n| Kaulas | 05 | 7,42,480-8 Annas |\n| Melangur | 03 | 67,987-0 Annas |\n| Elgandal | 21 | 12,19,507-4 Annas |\n| Warangal | 16 | 7,48,491 |\n| Khammamet | 11 | 6,29,323-13 |\n| Devarakonda | 13 | 21,19,616-4 |\n| Penagal | 05 | 4,55,215-14 |\n| Bhongir | 11 | 1,47,836-9 |\n| Akar-Kara | 06 | 5,18,228-12 |\n| Kovilkonda | 13 | 10,510,517-14 |\n| Ghanpura | 08 | 5,13,484-4 |\n| Murtuzanagar (Guntur) | 39 | 17,07,705-4 |\n| Machilipatnam | 08 | 2,87,000-0 |\n| Nizampatnam | – | 87,000-0 |\n| Eluru | 12 | 6,90,448-15 |\n| Mustafanagar | 24 | 12,00,160-15 |\n| Rajahmundry | 24 | 6,27,853-0 |\n| Sikkol | 115 | 9,09,242-11 |\n| Kanat-rent | – | 2,55,001-0 |\n\nSikkol Sarkar, with 115 Parganas, was the largest in the entire kingdom; the smallest was Melangur, with three Parganas. The highest revenue to the treasury came from Kovilkonda — 10,510,517-14 Annas.\n\n### Judicial System\n\nThe Qutb Shahi Sultans managed the legal system honouring both Hindu (local) and Islamic laws, making arrangements from village level to deal with civil and criminal cases. Qazis, Moulvis, and Hindu Pandits played key roles in solving cases.\n\nSpecial Courts were established — Dadmahal, founded by Sultan-Muhammad-Quli-Qutb Shah, and Aman-Mahal, founded by Abdullah Qutb Shah. The Sultan attended these special courts once a week, listened to cases, and delivered judgments with the help of Qazis and Pandits. French travellers Tavernier and Bernier appreciated the Qutb Shahi judicial system, noting that judges and the Sultan delivered judgments without fear or favour.", "free": false}, {"partNumber": 6, "conceptId": "telangana-history-en-chapter11-qutbshahi-rule-p6", "partName": "Socio-Religious Life of the People of Qutb Shahi Age", "bodyMd": "Glimpses of socio-religious life come from contemporary Telugu, Persian, and Arabic works and from foreign travellers like Tavernier, Bernier, and Thevenot.\n\nThe Qutb Shahi Sultans tried to maintain Hindu-Muslim unity through liberal policies. Works such as _Tariq-e-Ferishta_, _Tariq-e-Qutb Shah_, _Burhan-e-Masir_, and Telugu works like _Thapathi Samvaranophakhyanam_, _Yayathi Charita_, _Vaijayanthi Vilasam_, _Sukasapthati_, and _Hamsavimsathi_ give details about the social life of the people.\n\n**Society and daily ' WHERE chapter_slug = 'telangana-history-en-chapter11-qutbshahi-rule';
UPDATE theory_content SET concepts_json = concepts_json || 'life:** Palavekiri Kadiripathi, in his work _Sukasapthati_, described in detail the socio-religious life of Telangana people — dress, food habits, houses, and marriages of Brahmins, Vaishyas, and Sudras.\n\n*   Brahmins were engaged in ritual work, trade, and agriculture.\n*   Hindus employed in service of the Sultan wore long-size silk pyzamas and kurthas, and some wore long cloth caps.\n*   Reddys lived in grand houses; Reddy women wore many types of gold ornaments and costly sarees. Vaishyas were engaged in trade.\n*   A large number of sub-castes emerged during this age: Kapu, Reddy, Velama, Balija, carpenters, weavers, blacksmiths, boya, potter, tailor, fishermen, washermen, barbers, and others played significant roles in society.\n*   **Social evils:** Child marriages, dowry system, Sati, and prostitution prevailed. The condition of Sudras was miserable — they worked in fields and in the houses of rich people.\n*   Hindus and Muslims celebrated many festivals in a true spirit, both believing in orthodox practices — Holi, Ramzan, Muharram, Nauroz, Bakrid, Dasserah, and Deepavali were the main festivals.\n\n**Position of women:** The contemporary Telugu writer Ponnaganti Telaganarya, in his work _Yayathi Charita_, described the condition of women as not so good in general.\n\n*   A woman was respected only in domestic life; outside, she was given no freedom, living under the control of husband or mother-in-law. The position of widows was very pathetic.\n*   Purdah system was followed by both Hindu and Muslim women.\n*   Foreign travellers Tavernier, Methwold, and Frair wrote that women were considered a means of enjoyment by Sultans and their officials; child marriages, Sati, prostitution, and the Devadasi system were common evils.\n*   Women of royal families like Hayat Bakshi Begum and Chand Bibi excelled in fine arts and politics. Rural women spent most of their time in agricultural labour; some engaged in caste-based professions like weaving. Girls were generally trained in dance, music, and painting.\n*   Polygamy was common among both Hindus and Muslims. Courtesans were patronized by the ruling class — according to Tavernier, there were twenty thousand prostitutes in Hyderabad and Golconda fort, granted licenses by the government to carry on their profession.", "free": false}, {"partNumber": 7, "conceptId": "telangana-history-en-chapter11-qutbshahi-rule-p7", "partName": "Economy under Qutb Shahis", "bodyMd": "The Golconda Kingdom was one of the richest medieval kingdoms in the Deccan, owing to two main factors: the natural wealth of the kingdom, especially its rich diamond mines, and its fertile coastal land, water sources, and brisk foreign trade carried through Masulipatnam port with Central Asia and European countries.\n\n### Agriculture and Irrigational Facilities\n\nAgriculture was the chief occupation of the majority. Agricultural land was divided into two categories — Zamindari Lands and Haveli Lands. Agricultural work was carried out between June and October. Commercial crops like cotton, jute, pulses, fruits, and flowers were grown on a large scale; fruits and flowers flourished especially in Telangana, and Eluru in coastal Andhra was famous for indigo cultivation. Thevenot''s account described the different varieties of grapes cultivated in Telangana by the peasants.\n\n**Irrigation works:** Like the earlier Kakatiya rulers, the Qutb Shahi Sultans realized the importance of construction and maintenance of irrigational works, and many Kakatiya-era tanks were repaired.\n\n*   Under Ibrahim-Quli-Qutb Shah, Hussain-Sagar tank, Budwel tank, and Ibrahimpatnam tank were constructed.\n*   A tank was built at ''Durg,'' five kilometres from Golconda fort, supplying water to the royal family and officials through hydrological engineering skill.\n*   Ma-Saheb Tank was built by Khanam-Aga (popularly known as _Maseha_) near Saifabad to supply water to the local public.\n*   An inscription dated 1551 CE states that Ibrahim-Quli-Qutb Shah repaired the ''Pangal'' tank and ''Udaya Samudram'' tank; from the total product under these two tanks, the king was given a 1% share, peasants a 1½% share, Brahmins 1%, and soldiers 1%.\n*   Officials like Rahmatullah and Anthoji (Hawaldar) also encouraged repairing tanks and canals in the Nellore region; Nellore District inscriptions record that rich people, temple trustees, masjid boards, and village assemblies also extended liberal support for construction and repair, increasing the area of agricultural land and production.\n\n### Trade and Commerce\n\nInternal and external trade flourished during this period. Vaishyas (Komatis) played an active role in both. Arab and Portuguese traders supplied the best-breed horses to the Qutb Shahis. Telugu works _Sukasapthati_ and _Hamsavimsati_ provide details of the external trade of this age.\n\n*   After the advent of European trading companies, Masulipatnam, Kondapalli, Narasapuram, Madras, and Golconda emerged as famous trading centres.\n*   Internal trade was carried on bullock-carts, oxen, donkeys, and tangas; external trade was known as _Odaberamu_ (maritime trade).\n*   Masulipatnam, Motupalli, and Narasapuram were the chief ports; best-quality textiles were exported from Masulipatnam to European countries.\n*   Vasumata and Visnudasa were two rich traders of this period. Pilgrimage centres like Tirupati, Srisailam, and Srikalahasti also became famous trading centres.\n*   Golconda, Hyderabad, Warangal, Masulipatnam, Kondapalli, and Penugonda were the main urban centres; rural economy was in good condition, with weekly fairs (angadis) held in villages.\n*   Trade links flourished between Telangana, Andhra Pradesh, Karnataka, Tamil Nadu, Maharashtra, and Bengal. ''Perikas'' carried goods and grain from place to place in jute sacks on their heads or on oxen. Golconda''s traders maintained trade relations with the tradesmen of Gulbarga, Aurangabad, Bijapur, and Madras.\n*   Ship-building industry flourished at Narsapur and Masulipatnam. Nirmal and Indur were famous for the iron industry, producing best-quality swords.\n*   The Sultans encouraged trade through tax concessions and by appointing special officers to check weights and measurements, protecting the public from cheating by traders.\n*   The chief currency was Honnu, a gold coin foreigners described as ''Pagoda''; Panam, Thaar, and Kasu were other currency units. Kharkhanas were established by the Sultans to produce clothes and other articles for the royal family.\n*   Chief exports of the period included dress, cloth, diamonds, carpets, indigo, and best-quality swords; chief imports from Arabia, Central Asia, and Europe included horses, spices, gold, lead, dates, and crockery.\n\n### Industries of the Golconda Kingdom\n\nContemporary Telugu literary works, Farmans of the Sultans, and travel accounts of foreign traders provide valuable information about the flourishing industries of the period — diamond mining, diamond cutting and polishing, textile industry, carpet industry, ship-building industry, saltpetre industry, iron and steel industry, and Kalamkari industry. Skilled and trained persons alone were engaged in these industries, some of which depended on agricultural raw material and some on mineral resources; in some industries, work was done on a hereditary basis.\n\n**Diamonds and the diamond industry:** The Golconda Kingdom became very famous for its best-quality diamonds, which enjoyed great demand in the European market.\n\n*   ''Kollur'' near the Krishna River and Ramalla-Kota (Kurnool) were famous for the best-quality diamonds, and these mines existed since the pre-Qutb Shahi age — French traveller Tavernier noted the mines were in operation even during Vijayanagara times.\n*   In 1640 CE, when Tavernier visited the famous Kollur mine, nearly thirty thousand workers — men, women, and children — were engaged in digging, cleaning, and drying diamonds.\n*   World-famous diamonds like Kohinoor, Hope, Pitt, Pigot, and Nizam were found in the Golconda mines. Foreign travellers Francis-Co-Feria (1548 CE), Jaqude-Cotre (Spain), Nicolo-de-Conti (Italy), Tavernier, Bernier, Thevenot (all French), Garcia-de-Ortha, and William-Methwold also mentioned the Golconda diamond mines in their accounts. \n*   According to Tavernier, when he visited Golconda in 1645 CE, he saw the polishing of diamonds near the ''Carvan'' area, west of Charminar.\n*   The world-famous **Kohinoor Diamond** was found at Kollur mine in 1656 CE, during the reign of Abdullah-Qutb Shah; Tavernier also mentioned seeing the Kohinoor in the treasury of Aurangzeb. It weighed 106 carats, passed through many rulers, and was presented to Queen Victoria by Lord Laurence in 1849 after the conquest of Punjab; it is now preserved in the Imperial Rachegali Museum, England.\n*   The Sultans encouraged diamond trade by granting concessions to traders and leasing mining rights to contractors — according to Moorland, the Sultan received an income of nearly three lakh Pagodas from the Ramallakota mine every year, and good income from Kollur and other mines, while contractors also earned huge profits.\n\n**Textile industry:** Golconda textiles enjoyed great demand in the European market, produced in various qualities and colours (red, blue, white) by Golconda''s weavers; contractors paid weavers advances to secure products on time. Many types of flowers and leaves were printed on textiles and sarees; Chintz cloth was very popular. Kalankari cloth was produced by expert weavers at Masulipatnam, Palakollu, and Nizampatnam; best-quality calico cloth was produced at Narasapuram. Contemporary literature names varieties like Thanugudda, Lungi, Salempuri, and Palampur.\n\n**Carpet industry:** The Deccan was famous for best-quality carpets, and Warangal carpets earned a special place in the market. Mettawada and Girmajipeta areas of Warangal were inhabited by many Muslim carpet-weaving families; raw material for carpet-making was available in large quantity in Telangana. Sir George Watt, in his book _Indian Art at Delhi, Calcutta_, praised the great quality of Warangal carpets and the excellent colours used by carpet weavers.\n\n**Ship-building industry:** External trade with Persia and Europe flourished, with big vessels/ships used in sea voyages. Narsapuram, Bheemunipatnam, and Machilipatnam were important shipbuilding centres. Foreign travel accounts of Methwold and Shorer refer to the big and small ships prepared by experienced workers at Narsapur, made using best-quality teak wood and iron.\n\n**Saltpetre industry:** This industry, producing powder used in guns and firangis, flourished under the Qutb Shahis; Masulipatnam, Narsapuram, and Pulicat were famous for saltpetre products.", "free": false}, {"partNumber": 8, "conceptId": "telangana-history-en-chapter11-qutbshahi-rule-p8", "partName": "Progress of Telugu Literature under Qutb Shahis", "bodyMd": "The Qutb Shahi Sultans and their officials were great patrons and lovers of the Telugu language; some of them personally learned Telugu. The age of Ibrahim-Quli-Qutb Shah especially became famous for literary activity.\n\n*   Telugu poet Addanki Gangadhara was patronized by Ibrahim-Quli-Qutb Shah, dedicating his work _Thapathi Samvarnopakhyanam_ to the Sultan, who was praised by court poets as ''Malikiba-Rama.''\n*   Kandukuri Rudrakavi, author of _Niramkusopakhyanam_, was also honoured by Ibrahim-Quli-Qutb Shah — impressed by his scholarship, the Sultan granted him the village of ''Chintapalem'' as a gift.\n*   Aminkhan, the in-charge officer of Patancheru under Ibrahim-Quli-Qutb Shah, patronized another famous Telugu poet, Ponneganti Telaganarya, who dedicated his work _Yayati Charitam_ to Amin-Khan. This was the first Telugu work written in ''Achha Telugu.''\n*   Many Telugu scholars and poets wrote Chatu-verses praising Ibrahim-Quli-Qutb Shah''s great qualities.\n\n**Under Muhammad-Quli-Qutb Shah**, Telugu scholars and poets continued to receive liberal patronage:\n\n*   Ganesha Pandita was the court poet.\n*   Saranga Thammayya, another great Telugu poet at the court — originally the in-charge Revenue Officer (Karanam) of Golconda — wrote the popular Telugu work _Vaijayanthi Vilasam_.\n*   Kshetrayya, the famous Telugu ''Padakartha,'' was a contemporary of Abdullah-Qutb Shah; he visited Abdullah-Qutb Shah''s court and sang more than one thousand Padakeerthanas praising the Sultan. A native of ''Movva'' village in Krishna District, his Padakeerthanas became very popular throughout the Qutb Shahi kingdom.\n\n**Under the last Sultan, Abul Hassan Tanashah**, Telugu scholars continued to receive liberal support, including from the rulers of Jataprole and Gadwal Samsthans.\n\n*   Kancharla Gopanna (Bhakta Ramadas), the Revenue Officer (Tahsildar) of Khammam under Abul Hassan-Tanashah, constructed a temple to Lord Sri Rama at Bhadrachalam — he was later imprisoned for using public money for this construction. Tradition holds that while Gopanna languished in jail for the diverted revenue, Lord Rama and Lakshmana themselves appeared before Tanashah''s treasury and repaid the amount on his behalf, moving the Sultan to release him. He sang many keerthanas on Lord Sri Rama that became very popular throughout Andhradesa, becoming popularly known as Bhakta Ramadas; his work _Dasarathi Satakam_ is a classical work that received great appreciation from scholars.\n*   According to scholars, Prajakavi Yogivemana also belongs to this age — in his poetry, Vemana, in simple language, condemned the social evils and orthodox religious practices of the age.\n\nThus, Telugu literature under the Qutb Shahis continued to enjoy royal and popular support as in the Vijayanagara age; the Qutb Shahi Sultans and their officials did great service to the Telugu language.\n\n**Patronage of Hindu officials:** The Qutb Shahi Sultans honoured local customs and employed Hindus in positions of trust. Mahmud-Quli-Qutb Shah appointed a Hindu, Dharmarao, as his Commander-in-Chief, and another Hindu, Ganapathirao, as governor in charge of festivals and local administration. Fort commanders at key defensive strongholds such as Kondapalli, Koyilakonda, Kondaveedu, Ghanapuram, and Panagal were largely drawn from the Nayaka community.\n\nMuhammad-Quli-Qutb Shah himself composed poetry in Urdu, Persian, and Telugu, though his Telugu verses have not survived; his surviving Divans (poetry collections) in Persian and Urdu together run to about 1800 pages. Abdullah-Qutb Shah was also a devoted patron of learning and had several Sanskrit and Persian romantic tales translated into Urdu, including the tale of Yusuf and Zulaikha.", "free": false}, {"partNumber": 9, "conceptId": "telangana-history-en-chapter11-qutbshahi-rule-p9", "partName": "Art and Architecture", "bodyMd": "The Qutb Shahi Sultans were great lovers of fine arts, constructing many grand buildings — palaces, mosques, forts, asrukhanas, bridges, cities, hosp' WHERE chapter_slug = 'telangana-history-en-chapter11-qutbshahi-rule';
UPDATE theory_content SET concepts_json = concepts_json || 'itals, tombs, tanks, and sarais across their kingdom. Among the significant buildings of the Qutb Shahi age, Hyderabad city, Charminar, Mecca Masjid, Toli Masjid, Taramati Baradari, Puranapul, and Hussain Sagar are known even today for their beauty.\n\n### Charminar\n\nCharminar, the edifice of the four minarets, is the legendary masterpiece of the Qutb Shahis. This grand rectangular structure was built upon four grand arches by Muhammad-Quli-Qutb Shah in **1590–91 CE**, standing as an example of the artistic skill of Qutb Shahi masons and other workers.\n\n### Hyderabad (1590–91 CE)\n\nMuhammad-Quli-Qutb Shah (1580–1612 CE) was a great lover of architecture, and the city of Hyderabad was his own brainchild. It was constructed on the southern bank of the river Musi to accommodate the growing population of the Golconda Kingdom. There is no uniform opinion among historians regarding the real reason for the construction and naming of the city.\n\n**Planning and design:** In the mission of constructing Hyderabad, the Sultan received admirable support from his Peshwa, Mir-Momin Astrabadi, who hailed from a highly respected ''Moosavi'' Syed family of Astrabadi in the Gillon province of Iran — a Scholar, Administrator, Hakim, Engineer, and Alim. He reached Golconda in 1581 CE, won the Sultan''s favour, and rose to the position of ''Peshwa'' by 1585 CE.\n\n*   Mir-Momin Astrabadi planned Hyderabad on the model of ''Isfahan'' of Iran; he designed the first outline map of the city.\n*   The plan was a triangle marking the location of essential buildings, with Charminar as the centre, enclosed between the four arches with a plaza at the centre — replacing ''Maidan-i-Naqsh Jahan'' of Safawid Isfahan.\n*   Charminar was built where the four roads intersected: the northern road extended as far as the Musi river, the southern road went straight to Koh-i-Tur, the eastern road led to the coastal region of the Bay of Bengal, and the western road led to Golconda and beyond.\n*   Charkaman (Julukhana) was built eighty yards north of Charminar. The city extended on the northern side up to a hillock called Naubat Pahad (Ghat), beside which was Hussain Sagar.\n*   During Muhammad-Quli-Qutb Shah''s period, many beautiful gardens, mosques, palaces, sarais, buildings, and asrukhanas were constructed. Hyderabad attracted many scholars, artists, and Alims from Persia, becoming home to all peace-loving people and a centre of composite culture.\n\nThe poet-king Muhammad-Quli-Qutb Shah, on the eve of laying the city''s foundation, prayed that the city would bring peace and prosperity, and that people of all castes, creeds, and religions would make it their home like fishes in the ocean.\n\n**Contemporary praise:** An anonymous historian, writing in _Tarikh-e-Qutb Shahi_ (1616 CE) — twenty-five years after the city''s construction — described its beauty and pleasant atmosphere, noting that it lacked nothing and that even an old man hurrying to the city would recover his youth there.\n\nAnother historian, Muhammad Saqui, Court Chancellor of Aurangzeb, who accompanied the emperor during the 1687 siege of Golconda, described Hyderabad as the most pleasant place on earth, whose air and water purify the hearts of people and give them long life. Foreign travellers Tavernier, Bernier, and William Methwold also praised the climate, air, water, trees, and mountains of Hyderabad, calling it heaven on earth.\n\n### Darush-Shifa or House of Cure (1595 CE)\n\nMuhammad-Quli-Qutb Shah constructed Darush-Shifa, a Unani hospital, in 1595 CE for the treatment of poor people. Located close to Purani Haveli, it was a double-storied hospital-cum-residential college; doctors from various countries treated patients there, who were given free medicine and food.\n\n### Golconda Fort\n\nAccording to historians, Golconda fort was built during the Kakatiya period; the grand palaces, mosques, and buildings constructed by different Qutb Shahi Sultans stand as symbols of their imperial power and royalty. It was also known as Muhammadnagar. A traditional account holds that the name ''Golconda'' derives from ''Golla Konda'' (shepherd''s hill) in Telugu, from a legend of a shepherd boy who found an idol on the hill, prompting the Kakatiyas to build a mud fort at the spot.\n\n*   The founder, Sultan Quli, constructed a rock fort in place of the old mud fort.\n*   Ibrahim-Quli-Qutb Shah prepared a grand plan to strengthen the fort, constructing a 7-kilometre-long strong rock boundary with deep trenches, 87 semi-circular bastions (Burjus), and 8 Darwazas. Pettaburj, Moosaburj, and Kagaziburj are famous bastions located in the fort; Fateh Darwaja, Mecca Darwaza, Banjara Darwaza, Patanchru Darwaza, and Moti Darwaza are important gates.\n*   The most famous Fateh Darwaza (Fateh Gate) is 13 feet wide and 25 feet high; best-quality thick teak shutters and iron sheets with spikes were used to prevent elephants and enemies from battering the gate.\n*   Important buildings within the fort — Diwan-Mahal, Jami-Masjid, Bala Hissar, Nagina Bagh, Silah Khana, Ashurkhana, and Katora House — are known for their beauty.\n\n**Defense engineering:** The fort''s builders incorporated remarkable defensive features for its time.\n\n*   Molten lead and boiling oil could be poured onto attackers from the ramparts through openings above the gates, to prevent enemy soldiers and elephants from breaking through.\n*   A ''Kartalai wall'' (clapping wall) was built to allow guards to detect enemy movement by sound.\n*   The fort''s acoustic design allowed a hand-clap or particular sound made at the entrance dome (Fateh Darwaza) to be heard clearly at the Bala Hissar pavilion, nearly a kilometre away at the highest point of the fort — an ingenious early-warning system that is a striking example of the technical knowledge of the age.\n\nGolconda fort stands as a symbol of Qutb Shahi glory and imperial power; it was captured on **September 21, 1687**, by Aurangzeb''s forces.\n\n### Puranapul (1578 CE)\n\nPuranapul, an old bridge over the river Musi, was constructed by Ibrahim-Quli-Qutb Shah in 1578 CE. It has 22 arches, is 600 feet long, 35 feet broad, and 54 feet above the river bed. French traveller Tavernier, when he visited Hyderabad in 1676 CE, was very much impressed by its construction, describing it as the bridge of love and as beautiful as the ''Pont Neuf of Paris.''\n\n### Hussain Sagar (1562 CE)\n\nHussain-Shah-Wali, a famous Sufi saint and son-in-law of Ibrahim-Quli-Qutb Shah, constructed Hussain Sagar in 1562 CE, linking the twin cities of Hyderabad and Secunderabad. It is one and a half miles long and covers an area of eight square miles; the dam was fed by branches of the Balakpur river from the Musi, about 32 miles from Hyderabad.\n\n### Mecca Masjid\n\nSultan Muhammad Qutb Shah (1612–1626 CE) laid the foundation for this grand mosque under the guidance of Darga Mir Faizullah Baig and Chowdary Rajaiah. According to one version, construction started in 1614 CE; due to various reasons, it was completed only in 1693 CE, by the Mughal emperor Aurangzeb. Masons and stone-cutters from Persia and Arabia played a key role in its construction.\n\nLocated just 100 yards south-west of Charminar, the mosque takes its name from the Grand Mosque at Mecca, on which it is patterned. The hall measures 67 by 54 metres and is 23 metres high; the roof is supported by 15 arches, five on each of three sides, with the western side blocked by a high wall to provide the ''Mehrab.'' \n\nThis mosque is one of the largest in India and can accommodate ten thousand people for prayer at a time. According to French traveller Tavernier, the stone for the prayer niche was hewn out of a quarry and carried by several hundred pairs of bullocks to the site; when he visited in 1676 CE, nearly four thousand labourers, eight thousand masons, and two thousand cutters were engaged. It is believed that some bricks made from earth brought from Mecca were inserted over the central arch — this is why the mosque became popularly known as Mecca Masjid. Tavernier was very much impressed by the beauty of its pillars and arches.\n\n### Qutb Shahi Tombs\n\nThe tombs constructed by the Qutb Shahi Sultans became very popular for their magnificent architectural beauty. They are located one kilometre away from Golconda fort, near Banjara Darwaza.\n\n*   The tomb of Sultan-Quli-Qutb Shah is 9.5 metres square on a platform of 30.5 sq. metres; the tomb of Jamsheed is constructed on its south-western side.\n*   The tomb of Ibrahim-Quli-Qutb Shah is a quadrangular building with two rows of five arches, one over the other, giving it a two-storey effect.\n*   The tomb of Muhammad-Quli-Qutb Shah, founder of Hyderabad, is another wonderful construction — 42.5 metres high with a dome of 18.2 metres.\n*   The tombs of Muhammad-Qutb Shah and Abdullah-Qutb Shah are also built within this complex, as is the tomb of Hayat Bakshi Begum, daughter of Muhammad-Quli-Qutb Shah — a small mosque attached to her tomb is where Aurangzeb is said to have offered prayers during his Golconda campaign.\n\nToday the Qutb Shah Tombs stand as an example of excellent medieval Deccani Islamic architecture, are on the list of world monuments, and attract thousands of tourists every day. French traveller Tavernier was deeply impressed by their beauty; according to him, poor-feeding activity took place near the tombs every day at 4:00 pm.\n\n### Hayatnagar Mosque (1626 CE)\n\nHayat Baksh Begum, the only daughter of Muhammad-Quli-Qutb Shah, was known for her great qualities and knowledge in public service and state affairs.\n\n*   She constructed a tank named Ma-Saheba tank near Saifabad in 1625 CE.\n*   She built the Khairatabad Mosque in memory of her tutor, Ak-hund-mulla-Abdulmalik.\n*   She also built a village (16 miles east of Hyderabad) named Hayatnagar in 1626 CE, where a palace and mosque were also constructed.\n*   A grand Sarai was constructed by her near the Carvan area to facilitate travellers.\n\nShe died at the age of 76 in 1666 CE. Abdullah Qutb Shah, her son, built a beautiful mosque adjacent to her tomb within the complex of the Qutb Shahi Tombs.", "free": false}]' WHERE chapter_slug = 'telangana-history-en-chapter11-qutbshahi-rule';
